-- ============================================
-- LUMA — Thème 16 : LONG 2/3 x4 — Un road trip de la côte est avec plusieurs arrêts
-- ============================================


update scenarios set content = '{"characters": {"friend": "ton ami(e)", "surf_instructor": "le moniteur de surf", "tour_guide": "le guide"}, "start_node": "n1", "nodes": {"n1": {"speaker": "friend", "text": "Sydney to Cairns, three weeks, the whole east coast. Ready for this?", "text_fr": "Sydney à Cairns, trois semaines, toute la côte est. Prêt pour ça ?", "choices": [{"text": "Absolutely, I''ve been dreaming about this trip for months.", "text_fr": "Absolument, je rêve de ce voyage depuis des mois.", "next": "n2"}]}, "n2": {"speaker": "you_thought", "text": "(First stop: Byron Bay, known for its laid-back surfer vibe.)", "text_fr": "(Premier arrêt : Byron Bay, connue pour son ambiance surfeur décontractée.)", "choices": [{"text": "Let''s try surfing here, it seems like the perfect spot to start.", "text_fr": "Essayons de surfer ici, ça semble être l''endroit parfait pour commencer.", "next": "n3"}]}, "n3": {"speaker": "surf_instructor", "text": "First time surfing? Don''t worry, Byron''s waves are gentle for beginners.", "text_fr": "Première fois à surfer ? T''inquiète, les vagues de Byron sont douces pour les débutants.", "choices": [{"text": "I''m nervous but excited, let''s do this!", "text_fr": "Je suis nerveux mais excité, allons-y !", "next": "n4"}]}, "n4": {"speaker": "you_thought", "text": "(After a wobbly but thrilling first surf lesson, you both feel accomplished.)", "text_fr": "(Après une première leçon de surf branlante mais palpitante, vous vous sentez tous les deux accomplis.)", "choices": [{"text": "(Head north toward the next stop, salty and sun-kissed.)", "text_fr": "(Dirige-toi vers le nord vers le prochain arrêt, salé et bronzé.)", "next": "n5"}]}, "n5": {"speaker": "friend", "text": "Next stop, the Gold Coast! I''ve heard the beaches there are unreal.", "text_fr": "Prochain arrêt, la Gold Coast ! J''ai entendu dire que les plages là-bas sont irréelles.", "choices": [{"text": "Can''t wait, let''s find a good spot to camp for the night first.", "text_fr": "J''ai hâte, trouvons d''abord un bon endroit pour camper pour la nuit.", "next": "n6"}]}, "n6": {"speaker": "you_thought", "text": "(That night, van troubles strike — a flat tire in the middle of nowhere.)", "text_fr": "(Cette nuit-là, des problèmes de van surviennent — un pneu crevé au milieu de nulle part.)", "choices": [{"text": "(Work together to change the tire using the spare.)", "text_fr": "(Travaillez ensemble pour changer le pneu avec la roue de secours.)", "next": "n7"}, {"text": "(Call roadside assistance since neither of you has changed a tire before.)", "text_fr": "(Appelle l''assistance routière puisqu''aucun de vous n''a jamais changé de pneu.)", "next": "n7"}]}, "n7": {"speaker": "friend", "text": "(After fixing it together) Well, that''s one road trip skill we can now say we have!", "text_fr": "(Après l''avoir réparé ensemble) Bon, voilà une compétence de road trip qu''on peut maintenant dire avoir !", "choices": [{"text": "Ha, definitely a memorable way to learn it!", "text_fr": "Ha, définitivement une façon mémorable de l''apprendre !", "next": "n8"}]}, "n8": {"speaker": "you_thought", "text": "(Days later, you reach the Whitsundays, greeted by impossibly blue water.)", "text_fr": "(Des jours plus tard, vous atteignez les Whitsundays, accueillis par une eau impossiblement bleue.)", "choices": [{"text": "(Book a boat tour to explore the islands properly.)", "text_fr": "(Réserve une excursion en bateau pour explorer les îles correctement.)", "next": "n9"}]}, "n9": {"speaker": "tour_guide", "text": "Welcome aboard! Today you''ll see some of the most beautiful reef in the world.", "text_fr": "Bienvenue à bord ! Aujourd''hui vous allez voir l''un des plus beaux récifs du monde.", "choices": [{"text": "We''ve been looking forward to this for the whole trip!", "text_fr": "On attend ça avec impatience depuis le début du voyage !", "next": "n10"}]}, "n10": {"speaker": "you_thought", "text": "(Snorkeling among vibrant coral, you both feel truly present in the moment.)", "text_fr": "(En faisant du snorkeling parmi des coraux vibrants, vous vous sentez tous les deux vraiment présents dans l''instant.)", "choices": [{"text": "(Surface, breathless with excitement at what you just witnessed.)", "text_fr": "(Fais surface, essoufflé d''excitation face à ce que tu viens de voir.)", "next": "n11"}]}, "n11": {"speaker": "friend", "text": "That was honestly one of the most beautiful things I''ve ever seen.", "text_fr": "C''était honnêtement l''une des plus belles choses que j''aie jamais vues.", "choices": [{"text": "Agreed. This trip keeps outdoing itself with every stop.", "text_fr": "D''accord. Ce voyage se surpasse à chaque arrêt.", "next": "n12"}]}, "n12": {"speaker": "you_thought", "text": "(Finally, after three weeks, you arrive in Cairns, the trip''s final destination.)", "text_fr": "(Finalement, après trois semaines, vous arrivez à Cairns, la destination finale du voyage.)", "choices": [{"text": "(Look back at everything you''ve experienced along this coastline.)", "text_fr": "(Regarde en arrière tout ce que tu as vécu le long de cette côte.)", "next": "n13"}]}, "n13": {"speaker": "friend", "text": "Byron, the flat tire, the Whitsundays — what a journey this turned out to be.", "text_fr": "Byron, le pneu crevé, les Whitsundays — quel voyage ça s''est avéré être.", "choices": [{"text": "Every bump made it better, honestly. This trip changed something in me.", "text_fr": "Chaque bosse l''a rendu meilleur, honnêtement. Ce voyage a changé quelque chose en moi.", "next": "end_roadtrip"}]}, "end_roadtrip": {"speaker": "friend", "text": "Same here. The whole east coast, and we did it all together.", "text_fr": "Pareil pour moi. Toute la côte est, et on l''a fait tous ensemble.", "end": true, "ending_label": "Road trip côte est complété, souvenirs inoubliables 🏄🐠🚐"}}}'::jsonb, is_playable = true
where title = 'Un road trip de la côte est avec plusieurs arrêts'
  and theme_id = (select id from scenario_themes where position = 16 and language_id = (select id from languages where code = 'en'));
